style.css:
@-moz-document domain("pinterest.com") {
/* Background + general elements */
  body, html {
    background-color: #2c0e14 !important; /* deep maroon */
    color: #f5e9e9 !important;
    font-family: 'Georgia', 'Segoe UI', serif !important;
  }

  /* Main feed & boards */
  .NuxContainer, .App, .hJCNzW, .zI7 {
    background-color: #3b0f16 !important; /* wine red */
    color: #f3e3e3 !important;
  }

  /* Header Bar */
  header, .header, .tBJ {
    background-color: #1e0508 !important;
    color: #f5e9e9 !important;
    border-bottom: 1px solid #a86a6a !important;
  }

  /* Search Bar */
  input[type="search"], input[type="text"], .gUZ {
    background-color: #561f24 !important;
    color: #fceeee !important;
    border: 1px solid #9a5050 !important;
    border-radius: 10px !important;
  }

  /* Buttons */
  button, .Button, .RCK {
    background-color: #a83242 !important;
    color: #fff8f8 !important;
    border-radius: 10px;
    font-weight: bold;
    border: none !important;
  }

  button:hover, .Button:hover {
    background-color: #8b2b36 !important;
  }

  /* Pins */
  .GrowthUnauthPinImage, .CollectionItem {
    background-color: #3e1217 !important;
    border-radius: 10px;
    box-shadow: 0 4px 8px rgba(0,0,0,0.4);
  }

  /* Modal backgrounds */
  .Jea, .zI7.iyn.Hsu {
    background-color: #2b0c11 !important;
    color: #f5e9e9 !important;
  }

  /* Hide promoted pins / ads */
  [data-test-id="pin-ads"], .zI7.iyn.Hsu[data-test-id*="ads"] {
    display: none !important;
  }
}
